Definition regs_ok : ltac2:(zQ "60!r0!hg8!hqb!hr4!q9!hra>1E$3>2sr@1$1$4>4regs@2$2@1$0#5@1$5@1$0#k0P") := ltac2:(zQ "a0!r0!hra!hg8!j0!hqb!r6!hr4!q9!hrf!ig7\1E$6\2sr@1$2$7\4regs@2$4@1$0#5@1$1@1$0#k0>1r@1$1@1$0#5@3$3@1$1@1$0#k0@2$9^2^1@2$5^4@2$8^3^1").

#[using="Type"] Lemma regs_ok_upd : forall E sr regs rd v e,
  regs_ok E sr regs -> edenot E e = v ->
  regs_ok E (if bv_eqb rd 0 then sr else sr_upd sr (ridx rd) e)
            (if bv_eqb rd 0 then regs else regupd regs rd v).
Proof.
