(* [comment removed for export] *)
#[using="Type"] Lemma find_and_atom_k_some : forall sg ts y mm, find_and_atom_k sg ts = Some (y, mm) ->
  (0 < mm)%Z /\ Z.land (mm + 1) mm = 0%Z.
Proof.
