#[using="Type"] Lemma fold_lins_e_sg_sound : forall E sg ts acc,
  tden E (fold_right (fun t a => lins_e (sg * fst t) (snd t) a) acc ts) = (sg * tden E ts + tden E acc)%Z.
Proof.
