#[using="Type"] Lemma know_byte_lit_sound : forall E base kn rb rk b,
  know_ok segs E base kn ->
  know_byte_lit segs kn rb rk = Some b ->
  flat E (SA rb rk) 1 ->
  rdn segs base (adenot E (SA rb rk)) 1 = Some [Z_to_bv 8 b] /\ (0 <= b < 256)%Z.
