#[using="Type"] Lemma land_mask_narrow : forall x i j : Z, (0 <= i <= j)%Z -> (j <= 64)%Z -> (0 <= x < 2 ^ j)%Z ->
  Z.land x (2 ^ j - 2 ^ i)%Z = Z.land x (2 ^ 64 - 2 ^ i)%Z.
Proof.
