#[using="Type"] Lemma Forall_app_intro : forall {A} (P : A -> Prop) l1 l2,
  Forall P l1 -> Forall P l2 -> Forall P (l1 ++ l2).
Proof.
ltac2:(KReplay.run1z (kr_t_XAxSymExec3Sound ()) ["FPX_2"; "CarrySound"] "##&wh01Ah11Ph22l1h32l2h42H1p;1p;3p;2p;4p200R0g00;iR1p4p710p8P!s7#<lR2!s70=I!s5%R3p8g016Ij13TP1j30TP2j31Tg00fJR2j22Tg06T^j45Tg03HUj44Tf0R1p-0[R4f1R5#3R6f2R7#3R8f3R9?075R:f4R;?095R<P2A19519097A0;97/2<R<[A0971,2:A1;7590;9[R:f5R2A129770;\<P9P7P5P1C5P1n20010!s#$12!s-%0X38X26X14X03P:^38^26^14^03P1f6R1P2P;P9A012;!s'#!st$C4O5b4UUW3W2W1X00o"). Qed.


#[using="Type"] Lemma kimg_piece : forall E M (wa : saddr) w (V : word) (lo hi lo' hi' : Z),
  flat E wa (Z.of_nat w) ->
  kentry_ok segs E M (KImg lo hi) ->
  (lo <= lo')%Z -> (hi' <= hi)%Z ->
  ((hi' <= estart E wa)%Z \/ (estart E wa + Z.of_nat w <= lo')%Z) ->
  kentry_ok segs E (wbytes M (adenot E wa) (word_to_le_bytes w V)) (KImg lo' hi').
Proof.
